import {useState} from 'react';
import {Button} from '@ui/buttons/button';
import {ChatIcon} from '@ui/icons/material/Chat';
import {useCreateConversation} from './requests/use-create-conversation';
import {toast} from '@ui/toast/toast';
import {useAuth} from '@common/auth/use-auth';

interface StartChatButtonProps {
  recipientId: number;
  recipientName?: string;
  variant?: 'flat' | 'outline' | 'text' | 'raised' | 'link';
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  className?: string;
  fullWidth?: boolean;
}

export function StartChatButton({
  recipientId,
  recipientName,
  variant = 'outline',
  size = 'sm',
  className,
  fullWidth,
}: StartChatButtonProps) {
  const [isCreating, setIsCreating] = useState(false);
  const createConversation = useCreateConversation();
  const {hasPermission} = useAuth();

  if (!hasPermission('chat.send')) {
    return null;
  }

  const handleClick = async () => {
    setIsCreating(true);
    try {
      const conversation = await createConversation.mutateAsync({
        recipient_id: recipientId,
      });

      toast.positive(
        `Conversation with ${recipientName || 'user'} opened. Check your messages.`,
      );

      // Optionally trigger the chat widget to open
      // This would require exposing a global function or using an event
      const event = new CustomEvent('open-chat-widget', {
        detail: {conversationId: conversation.id},
      });
      window.dispatchEvent(event);
    } catch (error: any) {
      toast.danger(
        error.response?.data?.message ||
          'Failed to start conversation. Please try again.',
      );
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <Button
      variant={variant}
      size={size}
      onClick={handleClick}
      disabled={isCreating}
      startIcon={<ChatIcon />}
      className={className}
      style={fullWidth ? {width: '100%'} : undefined}
    >
      {isCreating ? 'Starting...' : 'Message'}
    </Button>
  );
}
